448	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
449	    if (!match) return { error: "Record not found (it may have already been removed)." };
450	    await deleteRecord(ctx.domain.name, match.id);
451	  } catch (e: any) {
452	    return { error: String(e?.message ?? e).slice(0, 200) };
453	  }
454	  revalidatePath(`/dashboard/domains/${domainId}`);
455	  return {};
456	}
