94	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
95	  const wh = normHost(want.host);
96	  const wa = want.answer.trim().toLowerCase();
97	  return existing.some((r) => {
98	    if (r.host !== wh) return false;
99	    if (r.type !== want.type) return false;
100	    if (r.answer.trim().toLowerCase() !== wa) return false;
101	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
102	    return true;
103	  });
104	}
105	
106	const recordInputSchema = z.object({
107	  host: z.string().max(120).default(""),
108	  type: z.enum(RECORD_TYPES),
109	  answer: z.string().min(1).max(2000),
110	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
111	  priority: z.coerce.number().int().min(0).max(65535).optional(),
112	});
113	
114	export type BulkResult = {
115	  error?: string;
116	  added?: string[];
117	  skipped?: string[];
118	  failed?: { record: string; reason: string }[];
119	  note?: string;
120	};
121	
122	function label(r: RecordInput): string {
123	  const h = normHost(r.host) || "@";
124	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
125	  return `${r.type} ${h} → ${pri}${r.answer}`;
126	}
127	
128	/**
129	 * Add many DNS records at once, skipping any that already exist. Powers the
130	 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
131	 */
132	export async function addDnsRecordsBulk(
133	  domainId: string,
134	  records: RecordInput[]
135	): Promise<BulkResult> {
136	  let ctx;
137	  try {
138	    ctx = await ownedActiveDomain(domainId);
139	  } catch (e) {
140	    return { error: errMsg(e) };
141	  }
142	  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
143	  if (records.length > 100) return { error: "Too many records in one request (max 100)." };
144	
145	  const clean: RecordInput[] = [];
146	  for (const raw of records) {
147	    const parsed = recordInputSchema.safeParse(raw);
148	    if (!parsed.success) {
149	      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
150	    }
151	    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
152	  }
153	
154	  let existing: DnsRecord[];
155	  try {
156	    existing = await listRecords(ctx.domain.name);
157	  } catch (e) {
158	    return { error: `Could not read current records: ${errMsg(e)}` };
159	  }
160	
161	  const added: string[] = [];
162	  const skipped: string[] = [];
163	  const failed: { record: string; reason: string }[] = [];
164	
165	  for (const rec of clean) {
166	    if (recordExists(existing, rec)) {
167	      skipped.push(label(rec));
168	      continue;
169	    }
170	    try {
171	      await addRecord(ctx.domain.name, {
172	        host: rec.host,
173	        type: rec.type,
174	        answer: rec.answer,
175	        ttl: rec.ttl ?? 300,
176	        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
177	      });
178	      added.push(label(rec));
179	      // Track locally so later records in the same batch dedupe correctly.
180	      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
181	    } catch (e) {
182	      failed.push({ record: label(rec), reason: errMsg(e) });
183	    }
184	  }
185	
186	  await db.auditLog.create({
187	    data: {
188	      userId: ctx.user.id,
189	      action: "domain.dns_bulk_add",
190	      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
191	    },
192	  });
193	  revalidatePath(`/dashboard/domains/${domainId}`);
194	  return { added, skipped, failed: failed.length ? failed : undefined };
195	}
