445	const lockStoreKey = (domainId: string) => `domain-lock:${domainId}`;
446	
447	export type LockView = { locked: boolean; live: boolean; note?: string; error?: string };
448	
449	export async function getRegistrarLock(domainId: string): Promise<LockView> {
