452	    ctx = await ownedDomain(domainId);
453	  } catch (e) {
454	    return { locked: false, live: false, error: errMsg(e) };
455	  }
456	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
457	    try {
458	      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}`);
459	      const locked = json?.locked === true;
460	      return { locked, live: true };
461	    } catch {
462	      /* fall through to stored intent */
