1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { registrarConfigured } from "./registrar";
7	
8	/* ------------------------------------------------------------------ *
9	 * Minimal name.com v4 client (Basic auth), mirroring lib/registrar.ts.
10	 * These endpoints aren't exposed by the shared registrar helper, so we
11	 * call them directly here. All calls are guarded by registrarConfigured().
12	 * ------------------------------------------------------------------ */
13	
14	function baseUrl(): string {
15	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
16	}
17	
18	function authHeader(): string {
19	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
20	  return "Basic " + Buffer.from(raw).toString("base64");
21	}
22	
23	async function nc(method: string, path: string, body?: unknown): Promise<any> {
24	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
25	  const res = await fetch(`${baseUrl()}${path}`, {
26	    method,
27	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
28	    body: body !== undefined ? JSON.stringify(body) : undefined,
29	    signal: AbortSignal.timeout(30_000),
30	  });
31	  const text = await res.text();
32	  let json: any = {};
33	  try {
34	    json = text ? JSON.parse(text) : {};
35	  } catch {
36	    /* non-JSON error body */
37	  }
38	  if (!res.ok) {
39	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
40	    throw new Error(`name.com: ${msg}`);
41	  }
42	  return json;
43	}
44	
45	function errMsg(e: unknown): string {
46	  return String(e instanceof Error ? e.message : e).slice(0, 200);
47	}
48	
49	const HOST_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;
50	
51	async function ownedDomain(domainId: string) {
52	  const user = await requireUser();
53	  const domain = await db.domain.findUnique({ where: { id: domainId } });
54	  if (!domain) throw new Error("Not found");
55	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
56	  return { user, domain };
57	}
