27	/**
28	 * Build an intent from raw query params. Anything unrecognised collapses to
29	 * `{ kind: "settings" }` (connect only, no auto-action) rather than erroring.
30	 */
31	export function parseIntent(params: {
32	  intent?: string | null;
33	  id?: string | null;
34	  host?: string | null;
35	}): CfConnectIntent {
36	  const kind = String(params.intent ?? "").trim();
37	  const id = String(params.id ?? "").trim();
38	  if (!(KINDS as readonly string[]).includes(kind)) return { kind: "settings" };
39	  if (kind === "settings") return { kind: "settings" };
40	  if (!ID_RE.test(id)) return { kind: "settings" };
41	  if (kind === "migration") {
42	    const host = String(params.host ?? "").trim().toLowerCase();
43	    return { kind: "migration", id, ...(host ? { host } : {}) };
44	  }
45	  return { kind: kind as "email" | "website", id };
46	}
